<?php declare(strict_types=1);
function lh_has_column(PDO $db,string $table,string $column):bool{try{$q=$db->prepare("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name=? AND column_name=?");$q->execute([$table,$column]);return (int)$q->fetchColumn()>0;}catch(Throwable){return false;}}
function lh_has_table(PDO $db,string $table):bool{try{$q=$db->prepare("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?");$q->execute([$table]);return (int)$q->fetchColumn()>0;}catch(Throwable){return false;}}
function lh_course(PDO $db,string $slug):?array{try{if(!lh_has_table($db,'learning_courses'))return null;$hasCat=lh_has_table($db,'learning_categories');$sql="SELECT c.*".($hasCat?',lc.name category_name,lc.icon category_icon,lc.slug category_slug':'')." FROM learning_courses c".($hasCat?' LEFT JOIN learning_categories lc ON lc.id=c.category_id':'')." WHERE c.slug=?".(lh_has_column($db,'learning_courses','enabled')?' AND c.enabled=1':'')." LIMIT 1";$q=$db->prepare($sql);$q->execute([$slug]);return $q->fetch(PDO::FETCH_ASSOC)?:null;}catch(Throwable){return null;}}
function lh_lessons(PDO $db,int $courseId):array{$hasCh=lh_has_column($db,'learning_lessons','chapter_id')&&lh_has_table($db,'learning_chapters');if($hasCh){$chapterTitle=lh_has_column($db,'learning_chapters','title')?'ch.title':(lh_has_column($db,'learning_chapters','name')?'ch.name':'NULL');$chapterOrder=lh_has_column($db,'learning_chapters','sort_order')?'ch.sort_order':'ch.id';try{$q=$db->prepare("SELECT l.*,{$chapterTitle} chapter_title FROM learning_lessons l JOIN learning_chapters ch ON ch.id=l.chapter_id WHERE ch.course_id=? AND l.enabled=1 ORDER BY {$chapterOrder},ch.id,l.sort_order,l.id");$q->execute([$courseId]);return $q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable){}}if(lh_has_column($db,'learning_lessons','course_id')){try{$q=$db->prepare("SELECT l.*,NULL chapter_title FROM learning_lessons l WHERE l.course_id=? AND l.enabled=1 ORDER BY l.sort_order,l.id");$q->execute([$courseId]);return $q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable){}}return [];}
function lh_lesson(PDO $db,string $slug):?array{$hasCh=lh_has_column($db,'learning_lessons','chapter_id')&&lh_has_table($db,'learning_chapters');$hasCat=lh_has_table($db,'learning_categories');$joinCat=$hasCat?' LEFT JOIN learning_categories lc ON lc.id=c.category_id':'';$catSel=$hasCat?',lc.name category_name':'';if($hasCh&&lh_has_column($db,'learning_chapters','course_id')){try{$q=$db->prepare("SELECT l.*,c.title course_title,c.slug course_slug{$catSel} FROM learning_lessons l JOIN learning_chapters ch ON ch.id=l.chapter_id JOIN learning_courses c ON c.id=ch.course_id{$joinCat} WHERE l.slug=? AND l.enabled=1 LIMIT 1");$q->execute([$slug]);if($r=$q->fetch(PDO::FETCH_ASSOC))return $r;}catch(Throwable){}}if(lh_has_column($db,'learning_lessons','course_id')){try{$q=$db->prepare("SELECT l.*,c.title course_title,c.slug course_slug{$catSel} FROM learning_lessons l JOIN learning_courses c ON c.id=l.course_id{$joinCat} WHERE l.slug=? AND l.enabled=1 LIMIT 1");$q->execute([$slug]);return $q->fetch(PDO::FETCH_ASSOC)?:null;}catch(Throwable){}}return null;}
function lh_lesson_nav(PDO $db,int $courseId,int $lessonId):array{$all=lh_lessons($db,$courseId);foreach($all as $i=>$r)if((int)$r['id']===$lessonId)return ['all'=>$all,'previous'=>$all[$i-1]??null,'next'=>$all[$i+1]??null,'position'=>$i+1];return ['all'=>$all,'previous'=>null,'next'=>null,'position'=>0];}
?>